1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	// diskBatch 是批量请求记录的磁盘格式。
10	type diskBatch struct {
11		ID       string         `json:"id"`
12		Operator string         `json:"operator"`
13		Time     time.Time      `json:"time"`
14		Devices  []diskBatchDev `json:"devices"`
15	}
16	
17	type diskBatchDev struct {
18		DeviceID    string          `json:"deviceId"`
19		Revision    uint64          `json:"revision"`
20		NewRevision uint64          `json:"newRevision"`
21		Config      json.RawMessage `json:"config"`
22	}
23	
24	func (s *Store) marshalBatches() map[string]diskBatch {
25		out := make(map[string]diskBatch, len(s.batches))
26		for id, b := range s.batches {
27			db := diskBatch{
28				ID:       b.ID,
29				Operator: b.Operator,
30				Time:     b.Time,
31				Devices:  make([]diskBatchDev, 0, len(b.Devices)),
32			}
33			for _, d := range b.Devices {
34				db.Devices = append(db.Devices, diskBatchDev{
35					DeviceID:    d.DeviceID,
36					Revision:    d.Revision,
37					NewRevision: d.NewRevision,
38					Config:      cloneRaw(d.Config),
39				})
40			}
41			out[id] = db
42		}
43		return out
44	}
45	
46	// restoreBatches 恢复批量请求记录并做一致性校验：标识、操作者、时间、
47	// 设备列表、配置、修订号都必须自洽，且每台设备的审计中必须存在带同一
48	// 请求标识的对应记录；任何损坏都拒绝打开整个存储。
49	// 旧存储没有批量记录时 disk 为 nil，正常打开。
50	func (s *Store) restoreBatches(disk map[string]diskBatch) error {
51		out := make(map[string]*batchRequestState, len(disk))
52		for id, db := range disk {
53			if id == "" || db.ID != id {
54				return fmt.Errorf("%w: batch request id mismatch", ErrCorruptStorage)
55			}
56			if db.Operator == "" || db.Time.IsZero() {
57				return fmt.Errorf("%w: batch request %s invalid", ErrCorruptStorage, id)
58			}
59			if len(db.Devices) == 0 {
60				return fmt.Errorf("%w: batch request %s has no devices", ErrCorruptStorage, id)
61			}
62			rec := &batchRequestState{ID: id, Operator: db.Operator, Time: db.Time}
63			seen := map[string]bool{}
64			for _, dd := range db.Devices {
65				if dd.DeviceID == "" || seen[dd.DeviceID] {
66					return fmt.Errorf("%w: batch request %s device list invalid", ErrCorruptStorage, id)
67				}
68				seen[dd.DeviceID] = true
69				dev, ok := s.devices[dd.DeviceID]
70				if !ok {
71					return fmt.Errorf("%w: batch request %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
72				}
73				if _, ok := decodeObject(dd.Config); !ok {
74					return fmt.Errorf("%w: batch request %s device %s config invalid", ErrCorruptStorage, id, dd.DeviceID)
75				}
76				if dd.NewRevision != dd.Revision+1 || dev.Revision < dd.NewRevision {
77					return fmt.Errorf("%w: batch request %s device %s revision mismatch", ErrCorruptStorage, id, dd.DeviceID)
78				}
79				// 设备审计中必须存在带同一请求标识、同一新修订号的记录。
80				found := false
81				for _, a := range dev.Audit {
82					if a.RequestID == id && a.Revision == dd.NewRevision {
83						found = true
84						break
85					}
86				}
87				if !found {
88					return fmt.Errorf("%w: batch request %s device %s audit missing", ErrCorruptStorage, id, dd.DeviceID)
89				}
90				rec.Devices = append(rec.Devices, batchDeviceState{
91					DeviceID:    dd.DeviceID,
92					Revision:    dd.Revision,
93					NewRevision: dd.NewRevision,
94					Config:      cloneRaw(dd.Config),
95				})
96			}
97			out[id] = rec
98		}
99		// 反向校验：审计中的非空请求标识必须对应一条已保存的批量记录
100		// （单设备修改的审计标识为空，无需补填）。
101		for devID, dev := range s.devices {
102			for _, a := range dev.Audit {
103				if a.RequestID == "" {
104					continue
105				}
106				if _, ok := out[a.RequestID]; !ok {
107					return fmt.Errorf("%w: device %s audit references unknown batch request %s",
108						ErrCorruptStorage, devID, a.RequestID)
109				}
110			}
111		}
112		s.batches = out
113		return nil
114	}
