		return dir
	}
	rewrite := func(t *testing.T, dir string, mutate func(map[string]any)) {
		data, err := os.ReadFile(filepath.Join(dir, storeFileName))
		if err != nil {
			t.Fatal(err)
		}
		var doc map[string]any
		if err := json.Unmarshal(data, &doc); err != nil {
			t.Fatal(err)
		}
		mutate(doc)
		out, err := json.Marshal(doc)
		if err != nil {
			t.Fatal(err)
		}
