	}
	// 批量记录配置损坏
	dir = newStore(t)
	rewrite(t, dir, func(doc map[string]any) {
		devs := batches(doc)["req-1"].(map[string]any)["devices"].([]any)
		devs[0].(map[string]any)["config"] = []any{1}
	})
	if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
		t.Fatalf("bad config: %v", err)
	}
	// 批量记录修订号与设备审计不一致
	dir = newStore(t)
	rewrite(t, dir, func(doc map[string]any) {
		devs := batches(doc)["req-1"].(map[string]any)["devices"].([]any)
